from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.E)
motor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
motor_2 = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(motor, motor_2, 87, 120)

# Initialize variables.
base_speed = 200
turn_amount = 25
target_white = 30


# The main program starts here.
# Start facing left on the bottom right corner facing north on the mat
# facing the back of the robot, the  lower right corner, not counting the
# wheels should alihgn with the line of the "g"
print(drive_base.angle())
# make sure to mesure all of the angles and distance the robot traveled
drive_base.straight(420)
print(drive_base.distance())
drive_base.turn(125)
print(drive_base.angle())
drive_base.straight(900)
print(drive_base.distance())
drive_base.turn(-125)
print(drive_base.angle())
drive_base.straight(490)
print(drive_base.distance())
drive_base.turn(125)
print(drive_base.distance())
drive_base.turn(145)
print(drive_base.distance())
drive_base.straight(50)
print(drive_base.distance())
drive_base.straight(160)
prime_hub.speaker.beep(500, 2000)
# *Beep of celebration*
print(drive_base.distance())
# Go back to home-base 😡
drive_base.straight(-150)
print(drive_base.distance())
drive_base.turn(65)
print(drive_base.distance())
drive_base.straight(1500)
